(A,+,\times)\text{ anneau }\iff
\begin{cases}
(A,+)\text{ groupe commutatif, neutre }0_A\\
\times \ associatif,\ \exists1_A\\
\times \ distributive \ par \ rapport \ à \ +
\end{cases}

(G, \cdot)\text{ groupe }\iff
\begin{cases}
\cdot \ associative  \\
\exists e\in G \\
\forall x\in G,\ \exists x^{-1}\in G
\end{cases}

\begin{cases}
1_A\in B\\
\forall x,y\in B,\ x-y\in B\\
\forall x,y\in B,\ xy\in B
\end{cases}

\begin{cases}
e\in H\\
\forall x,y\in H,\ x\cdot y\in H\\
